def fifth_Power_Sum(n: int) -> int:
    if n <= 0:
        return 0
    # Use the formula for the sum of fifth powers:
    # sum_{k=1}^n k^5 = (n^2 * (n+1)^2 * (2n^2 + 2n - 1)) / 12
    return (n**2 * (n+1)**2 * (2*n**2 + 2*n - 1)) // 12

def check_k_elements(tuple_list, k):
