def is_decimal(value) -> bool:
    if value is None:
        return False
    # Convert to string
    s = str(value).strip()
    # Reject scientific notation (contains 'e' or 'E')
    if 'e' in s.lower():
        return False
    # Quick check: must contain exactly one '.' and two digits after
    if '.' not in s:
        return False
    parts = s.split('.')
    if len(parts) != 2:
        return False
    integer_part, decimal_part = parts
    # Check decimal part length == 2 and all digits
    if len(decimal_part) != 2 or not decimal_part.isdigit():
        return False
    # Check integer part is a valid integer (with optional leading '-' sign)
    if integer_part == '':
        # e.g. ".12" -> treat as 0.12, so integer_part empty allowed
        # but '-' alone is not valid
        return True
    if integer_part == '-':
        return False
    if integer_part.startswith('-'):
        integer_part = integer_part[1:]
    if integer_part and not integer_part.isdigit():
        return False
    return True

def is_Two_Alter(s: str) -> bool:
    if len(s) < 2:
        return False
    distinct_chars = set(s)
    if len(distinct_chars) != 2:
        return False
    for i in range(len(s) - 1):
        if s[i] == s[i+1]:
            return False
    return True

def max_sub_array_sum(arr, length):
    if length == 0:
        return 0

    max_so_far = arr[0]
    max_ending_here = arr[0]

    for i in range(1, length):
        max_ending_here = max(arr[i], max_ending_here + arr[i])
        max_so_far = max(max_so_far, max_ending_here)

    return max_so_far

def double_the_difference(lst):
    '''
    Given a list of numbers, return the sum of squares of the numbers
    in the list that are odd. Ignore numbers that are negative or not integers.
    '''
    return sum(x*x for x in lst if isinstance(x, int) and x > 0 and x % 2 == 1)

def count_nums(arr):
    def signed_digit_sum(n):
        s = str(abs(n))
        digits = list(map(int, s))
        if n < 0:
            digits[0] = -digits[0]
        return sum(digits)

    return sum(1 for x in arr if signed_digit_sum(x) > 0)

from typing import List, Tuple

def sum_product(numbers: List[int]) -> Tuple[int, int]:
    total_sum = 0
    total_product = 1
    for num in numbers:
        total_sum += num
        total_product *= num
    return (total_sum, total_product)

