def even_odd_palindrome(n):
    if n == 0:
        return (0, 0)

    even_count = 0
    odd_count = 0

    for num in range(1, n + 1):
        s = str(num)
        if s == s[::-1]:  # palindrome check
            if num % 2 == 0:
                even_count += 1
            else:
                odd_count += 1

    return (even_count, odd_count)

def correct_bracketing(brackets: str):
    count = 0
    for char in brackets:
        if char == '<':
            count += 1
        else:  # char == '>'
            count -= 1
            if count < 0:
                return False
    return count == 0
